INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 20, 'theory', 'Quiz: CSS Grid');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 0, 'What is the fundamental difference between grid and flexbox?', '["Grid works only with data tables", "Grid lays out items along two axes at once, rows and columns, while flexbox works along one axis", "Flexbox can set gaps, and grid can''t", "Grid turns on only inside a media query"]', 1, 'Flexbox is one-dimensional: a row or a column, with sizes dictated by the content. Grid is two-dimensional: the container describes both rows and columns, and items fall into cells. Both have gap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 1, 'What does grid-template-columns: 200px 1fr 2fr mean?', '["Three columns of 200 pixels each", "Three equal columns", "A 200px column and two columns that split the remainder equally", "A 200px column and two columns that split the remainder in the ratio one to two"]', 3, 'First the fixed sizes and gaps are subtracted, and the remainder is split by shares: one share and two shares. The second column ends up half as wide as the third.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 2, 'What does repeat(auto-fit, minmax(200px, 1fr)) do?', '["Creates as many columns of at least 200px as fit in a row and stretches them to the full width", "Always creates exactly one column 200px wide", "Creates two columns: 200px and one share", "Works only together with media queries for every window width"]', 0, 'The browser counts the columns itself using the 200px minimum, and splits the remainder equally through 1fr. This way the grid rearranges itself without a single media query. Auto-fill differs in that it keeps empty tracks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 3, 'What does grid-column: 1 / -1 mean?', '["The item takes only the first column", "The item is hidden from the grid", "The item stretches from the first to the last line of the explicit grid, that is, across the whole row", "The item takes the column numbered minus one"]', 2, 'Lines are numbered from one, left to right, and negative numbers count from the end: minus one is the last line of the explicit grid. The declaration works with any number of columns.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 4, 'How does place-items differ from place-content?', '["place-items moves the whole grid, and place-content aligns the content of cells", "place-items aligns items inside cells, and place-content moves the grid itself inside the container", "They are two names for the same property", "place-items works only in flexbox, and place-content only in grid"]', 1, 'Items is about the contents of cells (align-items and justify-items), content is about the position of the tracks in the container when they don''t fill all the space. For a single item there are align-self and justify-self.');
